pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;

    // Heavily penalize dead space
    if post_residual > 0 && post_residual < 10 {
        score += 80.0 * (1.0 - progress);
    }

    // Penalize opportunity destruction
    if bin_residual >= next_item_size && post_residual < next_item_size {
        score += 40.0 * (progress / 2.0);
    }

    // Reward exact and near-exact matching
    if post_residual == next_item_size || (post_residual >= next_item_size && post_residual - next_item_size < 10) {
        score -= 60.0 * progress;
    }

    // Last chance awareness
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress);
    }

    // Dynamic horizon awareness
    let dynamic_horizon_penalty = post_residual / bin_capacity as f64 * (1.0 - progress) * open_bins_count as f64;
    score += dynamic_horizon_penalty;

    score
}
